def calculate_level_i_pending_workload(task_set, current_time, P_i):
    pending_workload = 0
    for task_h in task_set:
        if task_h.priority >= P_i:
            for job_h in task_h.released_jobs:
                if job_h.release_time < current_time and not job_h.is_finished():
                    pending_workload += job_h.remaining_execution_time
    return pending_workload

def find_level_i_active_period(task_set, P_i, start_search_time):
    # This is a conceptual sketch, actual implementation involves simulation or busy-period analysis
    a = find_time_when_workload_is_zero(task_set, P_i, start_search_time)
    if a is None: return None

    b = find_next_time_when_workload_is_zero(task_set, P_i, a)
    if b is None: return None

    # Verify workload is positive between a and b
    for t in range(a + 1, b):
        if calculate_level_i_pending_workload(task_set, t, P_i) <= 0:
            return None # Not a valid active period

    return (a, b)

def calculate_S_i_j_yao(task_i, j, b_i, task_set):
    S_previous = b_i + task_i.C - task_i.q_li + sum(task_h.C for task_h in task_set.hp(task_i))
    S_current = 0

    while True:
        interference_hp = 0
        for task_h in task_set.hp(task_i):
            interference_hp += (math.floor(S_previous / task_h.T) + 1) * task_h.C

        S_current = b_i + j * task_i.C - task_i.q_li + interference_hp

        if S_current == S_previous:
            break
        S_previous = S_current
    return S_current

def calculate_R_i_yao(task_i, task_set):
    # This is a conceptual sketch, actual implementation involves iterating over jobs in the active period
    max_F_i_j = 0
    # Assume we have a way to find jobs within the critical level_i_active_period
    for j in range(num_jobs_in_active_period):
        S_i_j = calculate_S_i_j_yao(task_i, j, b_i, task_set) # b_i needs to be determined
        F_i_j = calculate_F_i_j_yao(S_i_j, task_i.q_li)
        if F_i_j > max_F_i_j:
            max_F_i_j = F_i_j
    return max_F_i_j

