def calculate_RCB_i_x(task_i, x, ECB_i, ECB_sets, UCB_x_sets):
    RCB_i_x_multiset = Multiset()
    for m in ECB_i:
        ub_m_i_x_val = calculate_ub_m_i_x(m, task_i, x, ECB_sets, UCB_x_sets)
        for _ in range(ub_m_i_x_val):
            RCB_i_x_multiset.add(m)
    return RCB_i_x_multiset

def is_RCB_i_x_valid_multiset(RCB_i_x_multiset, actual_reloads_per_block):
    for m, count in RCB_i_x_multiset.items():
        if count < actual_reloads_per_block[m]:
            return False # Not an upper bound
    return True

def is_CRPD_h_i_x_upper_bound(CRPD_h_i_x_multiset, actual_crpd_values_per_pp):
    # For each element in the multiset, it should be >= the actual CRPD at that preemption point.
    # This is a conceptual check, as 'actual_crpd_values_per_pp' is hard to obtain.
    return all(crpd_val >= actual_crpd_values_per_pp[idx] for idx, crpd_val in enumerate(CRPD_h_i_x_multiset))

def calculate_gamma_union_i_x_t(task_i, x, t, RCB_i_x, hp_i_tasks, task_set, BRT):
    aggregated_evicting_blocks = Multiset()
    for task_h in hp_i_tasks:
        num_releases = math.floor(t / task_h.T)
        for _ in range(num_releases):
            for block in task_h.ECB_set:
                aggregated_evicting_blocks.add(block)

    intersecting_blocks = RCB_i_x.intersection(aggregated_evicting_blocks)
    return intersecting_blocks.size() * BRT

