def calculate_gamma_h_i_x_t(task_h, task_i, x, t, CRPD_h_i_x_multiset):
    num_preemptions_h = math.floor(t / task_h.T)

    if x <= num_preemptions_h:
        return sum(CRPD_h_i_x_multiset.values()) # Sum all elements in the multiset
    else:
        # Sort CRPD values and take the top num_preemptions_h
        sorted_crpd_values = sorted(CRPD_h_i_x_multiset.values(), reverse=True)
        return sum(sorted_crpd_values[:num_preemptions_h])

def calculate_gamma_plus_i_x_t(task_i, x, t, hp_i_tasks, task_set):
    total_crpd = 0
    for task_h in hp_i_tasks:
        crpd_from_h = calculate_gamma_h_i_x_t(task_h, task_i, x, t, task_set.CRPD_h_i_x_multiset(task_h, task_i, x))
        total_crpd += crpd_from_h
    return total_crpd

def calculate_b_i(task_i, lp_i_tasks, task_set):
    max_blocking = 0
    for task_l in lp_i_tasks:
        q_max_l_val = calculate_q_max_i(task_l, task_set.hp(task_l), task_set, BRT) # q_max_l depends on hp(l)
        if q_max_l_val > max_blocking:
            max_blocking = q_max_l_val
    return max_blocking
